--
-- Name: current_branch_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_branch_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  select branch_id from public.profiles where id = auth.uid();
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  insert into public.profiles (id, full_name, username, role)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'full_name', ''),
    coalesce(new.raw_user_meta_data->>'username', new.email),
    coalesce(new.raw_user_meta_data->>'role', 'cashier')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;


--
-- Name: handle_sale_item_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_sale_item_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  is_recipe boolean;
begin
  if new.product_id is not null then
    select is_recipe_product into is_recipe from public.products where id = new.product_id;

    if coalesce(is_recipe, false) = false then
      update public.products
        set stock_quantity = stock_quantity - new.quantity
        where id = new.product_id;
    end if;

    insert into public.inventory_movements (product_id, type, quantity, reason, created_by, branch_id)
    values (new.product_id, 'sale', -new.quantity, 'بيع - فاتورة', auth.uid(), new.branch_id);
  end if;
  return new;
end;
$$;


--
-- Name: handle_user_login(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_user_login() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if new.last_sign_in_at is distinct from old.last_sign_in_at then
    update public.profiles set last_login_at = new.last_sign_in_at where id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin');
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


